public class Solution {
    public static double average(int[] scores) {
        if (scores == null || scores.length == 0) {
            throw new IllegalArgumentException("scores must be non-empty");
        }
        int sum = 0;
        for (int s : scores) sum += s;
        return sum / scores.length;
    }
}

